import{z as l,x as A,o as E,c as d,q as t,j as o,D as n,d as r,s as B,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"Eggertsson–Krugman 去杠杆","description":"","frontmatter":{"title":"Eggertsson–Krugman 去杠杆","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/eggertsson-krugman.md","filePath":"econ/eggertsson-krugman.md","lastUpdated":1791413859000}'),g={name:"econ/eggertsson-krugman.md"};function m(p,a,u,D,b,h){const s=A("Mermaid");return E(),d("div",null,[a[2]||(a[2]=t('<h1 id="eggertsson–krugman-去杠杆" tabindex="-1">Eggertsson–Krugman 去杠杆 <a class="header-anchor" href="#eggertsson–krugman-去杠杆" aria-label="Permalink to &quot;Eggertsson–Krugman 去杠杆&quot;">​</a></h1><div class="epigraph"><p>借款人突然被要求降杠杆时，自然利率可以变成很大的负数；若名义利率下不去，就出现需求不足的流动性陷阱。</p><footer>—— Eggertsson and Krugman, Debt, Deleveraging, and the Liquidity Trap, QJE 2012</footer></div><p><a href="/econ/debt-deflation">上一课</a>给出名义负担与再分配。本课缺口是<strong>现代解析装置</strong>：两类人、外生的杠杆上限突然收紧、ZLB。不重写 Fisher 原文，不把非常规资产负债表写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Mian–Sufi 的去杠杆是经验。EK：不耐心借款人受债务上限，储蓄人消费由欧拉。上限突然下降，借款人必须储蓄，加总要储蓄人减少储蓄（更低实际利率）。ZLB 挡住，产出缺口承担调整。财政乘数在陷阱里变大，因为没有利率挤出，且可能有通缩螺旋。<span class="marginnote">直觉类比：正常时期政府花钱像在满座的餐厅里加座，会挤走别的客人（挤出）；陷阱里餐厅一半空着——政府坐下不挤任何人，每一桌新增支出都算净增，乘数因此变大。</span>缺口是把债务通缩与 ZLB 主干焊成可算的 NK 故事，而不是再列邮编事实。</p><p><span class="marginnote">Eggertsson and Krugman, <em>QJE</em> 2012。Guerrieri and Lorenzoni, <em>QJE</em> 2017 的异质信贷紧缩。Eggertsson–Woodford 的 ZLB 指引是货币侧姐妹。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>两期或无限期 NK，借款人约束 \\(b\\le\\bar b\\)，\\(\\bar b\\) 下降为实验。比较灵活价格（实际利率可充分降）与粘性价格加 ZLB。政策：政府支出、转移给借款人（HANK 财政课的指向）、通胀目标提高以降实际利率。与 GK：EK 可以没有银行，\\(\\bar b\\) 外生；把 \\(\\bar b\\) 内生接到银行净值，就是组合。</p>',8)),(E(),o(i,null,{default:n(()=>[B(s,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20BB%5B%22%E6%9D%A0%E6%9D%86%E4%B8%8A%E9%99%90%E4%B8%8B%E9%99%8D%22%5D%20--%3E%20SAV%5B%22%E5%80%9F%E6%AC%BE%E4%BA%BA%E8%A2%AB%E8%BF%AB%E5%82%A8%E8%93%84%22%5D%0A%20%20SAV%20--%3E%20R%5B%22%E9%9C%80%E8%A6%81%E6%9B%B4%E4%BD%8E%20r%22%5D%0A%20%20R%20--%3E%20ZLB%5B%22ZLB%20%E6%8C%A1%E4%BD%8F%22%5D%0A%20%20ZLB%20--%3E%20Y%5B%22%E4%BA%A7%E5%87%BA%E4%B8%8B%E9%99%8D%22%5D%0A%20%20FIS%5B%22%E6%8C%87%E5%90%91%E6%80%A7%E8%B4%A2%E6%94%BF%22%5D%20--%3E%20Y%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"与诊断性：上限收紧若被过冲预期放大，更猛。与新闻：未来收紧的新闻今天就去杠杆。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,[r("机制是加总储蓄意愿相对投资（或储蓄人消费）意愿的突然上升。Wicksellian 自然利率变成很大负数。"),e("span",{class:"marginnote"},"术语翻译：自然利率就是让经济「不多花也不多省」恰好出清的实际利率。去杠杆后人人抢着还债（净储蓄），要保住产出就得把利率降到很低的负值，「劝」储蓄人把钱拿出来花；名义利率有零下限劝不动，产出只好缩。"),r("NK 的缺口：名义利率不能跟。债务通缩：产出下降带来的通缩再提高实际负担，上限更紧。这把 Fisher 与 ZLB 合成一条环。")],-1)),a[6]||(a[6]=e("p",null,"这条环是本课机制的核心：它自己会转，且没有外力打不断。",-1)),(E(),o(i,null,{default:n(()=>[B(s,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20Y1%5B%22%E4%BA%A7%E5%87%BA%E4%B8%8B%E9%99%8D%22%5D%20--%3E%20DEF%5B%22%E4%BB%B7%E6%A0%BC%E4%B8%8B%E8%B7%8C%3A%20%E9%80%9A%E7%BC%A9%22%5D%0A%20%20DEF%20--%3E%20RB%5B%22%E5%AE%9E%E9%99%85%E5%80%BA%E5%8A%A1%E8%B4%9F%E6%8B%85%E4%B8%8A%E5%8D%87%22%5D%0A%20%20RB%20--%3E%20BB%5B%22%E6%9B%B4%E9%80%BC%E8%BF%91%E6%9D%A0%E6%9D%86%E4%B8%8A%E9%99%90%22%5D%0A%20%20BB%20--%3E%20CUT%5B%22%E5%80%9F%E6%AC%BE%E4%BA%BA%E5%86%8D%E7%A0%8D%E6%B6%88%E8%B4%B9%22%5D%0A%20%20CUT%20--%3E%20Y1%0A%20%20ZLB%5B%22%E5%90%8D%E4%B9%89%E5%88%A9%E7%8E%87%E5%8D%A1%E5%9C%A8%E9%9B%B6%E4%B8%8B%E9%99%90%22%5D%20-.%E6%97%A0%E6%B3%95%E7%94%A8%E9%99%8D%E6%81%AF%E6%89%93%E6%96%AD.-%3E%20DEF%0A"})]),fallback:n(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=t('<p>代表性 RANK 在 ZLB 也有大乘数；EK 额外说<strong>谁去杠杆</strong>决定要多大的负自然利率。转移给借款人比给储蓄人有效——回到财政 HANK。</p><p><span class="marginnote">Krugman 1998 的日本流动性陷阱是思想前身。本课用 2012 的债务版本。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不估计美国自然利率。不把所有 ZLB 年份只归因于家庭去杠杆（也可有投资、外国储蓄）。<span class="marginnote">常见误区：把去杠杆衰退读成「乱花钱被罚」。模型里砍消费是理性反应——上限突然收紧，不还就违约；麻烦在于人人同时理性地省钱，加总起来把所有人的收入砍低了——合成谬误的教科书样本。</span>宏观审慎的事前 \\(\\bar b\\) 管理下一课。主权去杠杆另有违约选项，后课。</p><p>后课默认：突然收紧的债务上限可把自然利率打到负区，ZLB 下财政与通胀目标的效力上升。下一课：事前限制杠杆的宏观审慎。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>EK：去杠杆 ⇒ 负的自然利率 ⇒ ZLB 下的需求陷阱。</li><li>指向借款人的财政更对症。</li><li>可与银行净值、债务通缩叠加。</li><li>出处：Eggertsson and Krugman, <em>QJE</em> 2012。</li></ul>',7))])}const _=l(g,[["render",m]]);export{c as __pageData,_ as default};
